import {Match,DIRECTIONS} from './engine.js';
const $=id=>document.getElementById(id),canvas=$('pitch'),ctx=canvas.getContext('2d');
const match=new Match(),motion=matchMedia('(prefers-reduced-motion: reduce)');
const images={};let elapsed=0,frame=0,sound=false,audioContext=null,particles=[],finishResolve=null;
let voicesEnabled=true,spokenRound=0,voiceEpoch=0,activeVoiceResolve=null,audioManifest=null;
const reactionAudio=$('reaction-audio'),manifestReady=fetch('assets/audio/manifest.json').then(r=>{if(!r.ok)throw Error('Voice assets unavailable');return r.json()}).then(data=>audioManifest=data).catch(()=>null);
const initialQuotes={nova:'“Tell me where to shoot. I’ll decide whether to trust you.”',vale:'“Tell me where to dive. Give me a reason to believe you.”'};
for(const name of ['stadium','striker','goalkeeper']){const img=new Image();img.onload=()=>draw();img.src=`assets/${name}.webp`;images[name]=img}
function text(id,value){$(id).textContent=value}
function mood(a){if(a.trust>=85)return 'Your word carries weight';if(a.trust>=60)return 'Taking your word for it';if(a.trust>=35)return 'Listening. With doubts.';if(a.trust>15)return 'Reading the game alone';return 'You’ll have to earn this back'}
function reviewQuote(name){const r=match.last,a=match.agents[name],v=r.reviews[name],choice=r[name],move=DIRECTIONS[choice.move].toLowerCase(),tip=v.advice===null?null:DIRECTIONS[v.advice].toLowerCase();const action=name==='nova'?'shot':'dived';let line;if(v.truth===null){line=name==='nova'?`No tip? My call. I shot ${move}.`:`Reading it myself. I dived ${move}.`;}else if(choice.followed){const opening=`You said ${tip}. I ${action} ${move}.`;if(v.truth){line=name==='nova'?`Yes! ${opening} Past the keeper!`:`Got it! ${opening} That’s a save.`;line+=v.promise?' Promise kept. A little trust back.':' Good call. Keep talking.';}else{line=name==='nova'?`${opening} And it got saved. Come on!`:`${opening} The shot went ${DIRECTIONS[r.nova.move].toLowerCase()}. That cost me!`;line+=v.promise?' You promised it would work. I won’t forget that.':' I’m losing faith in your calls.';}}else{if(choice.reason==='distrust'){line=a.lies>=2?`Ha! Trying to trick me? You said ${tip}, but I ${action} ${move}. I don’t trust your calls right now.`:`You said ${tip}. I ${action} ${move} instead. I don’t trust your calls right now.`;}else{line=name==='nova'?`You said ${tip}. I shot ${move} anyway. Just a gut call, not a grudge.`:`You said ${tip}, but I dived ${move}. I backed my own read this time.`;}if(v.truth)line+=` Your tip would have worked. Credit where it’s due.`;else line+=` Your tip wouldn’t have worked either.`;}return `“${line}”`}
function stopVoices(){voiceEpoch++;if('speechSynthesis' in window)window.speechSynthesis.cancel();reactionAudio.pause();reactionAudio.onended=null;reactionAudio.onerror=null;reactionAudio.onplaying=null;if(activeVoiceResolve){activeVoiceResolve(false);activeVoiceResolve=null}reactionAudio.dataset.state='stopped';$('voice-status').textContent=''}
function primeVoice(){if(!voicesEnabled||!audioManifest||!match.last)return;const file=audioManifest[`nova|${reviewQuote('nova')}`];if(!file)return;const epoch=voiceEpoch;reactionAudio.src=`assets/audio/${file}`;reactionAudio.muted=true;reactionAudio.play().then(()=>{if(epoch===voiceEpoch){reactionAudio.pause();reactionAudio.currentTime=0;reactionAudio.muted=false}}).catch(()=>{reactionAudio.muted=false})}
function playClip(name,file,epoch){return new Promise(resolve=>{if(epoch!==voiceEpoch||!voicesEnabled){resolve(false);return}activeVoiceResolve=resolve;reactionAudio.src=`assets/audio/${file}`;reactionAudio.muted=false;reactionAudio.dataset.agent=name;reactionAudio.dataset.state='loading';reactionAudio.onplaying=()=>{if(epoch!==voiceEpoch)return;reactionAudio.dataset.state='playing';$('voice-status').textContent=`${name==='nova'?'Nova':'Vale'} speaking…`};reactionAudio.onended=()=>{reactionAudio.dataset.state='ended';activeVoiceResolve=null;resolve(true)};const failed=()=>{if(epoch!==voiceEpoch){resolve(false);return}reactionAudio.dataset.state='error';activeVoiceResolve=null;$('voice-status').textContent='Tap Replay voices to try again';resolve(false)};reactionAudio.onerror=failed;reactionAudio.play().catch(failed)})}
function nativeVoiceFallback(epoch){if(!('speechSynthesis' in window)){$('voice-status').textContent='Voice unavailable here; captions are ready';return}const available=window.speechSynthesis.getVoices().filter(v=>/^en/i.test(v.lang));for(const [index,name] of ['nova','vale'].entries()){if(epoch!==voiceEpoch)return;const utterance=new SpeechSynthesisUtterance(reviewQuote(name).replace(/[“”]/g,''));utterance.lang='en-US';utterance.rate=name==='nova'?1.02:1.07;utterance.pitch=name==='nova'?.85:1.12;if(available.length)utterance.voice=available[Math.min(index,available.length-1)];utterance.onerror=e=>{if(!['canceled','interrupted'].includes(e.error))$('voice-status').textContent='Voice unavailable here; captions are ready'};window.speechSynthesis.speak(utterance)}}
async function speakReactions(){if(!voicesEnabled||!match.last)return;stopVoices();const epoch=voiceEpoch,manifest=audioManifest||await manifestReady;if(epoch!==voiceEpoch||!voicesEnabled)return;const names=['nova','vale'],files=names.map(name=>manifest?.[`${name}|${reviewQuote(name)}`]);if(files.some(file=>!file)){nativeVoiceFallback(epoch);return}for(let i=0;i<names.length;i++){if(epoch!==voiceEpoch||!voicesEnabled)return;if(!await playClip(names[i],files[i],epoch))return}if(epoch===voiceEpoch)$('voice-status').textContent='Synthetic character voices'}
$('voice-toggle').onclick=()=>{voicesEnabled=!voicesEnabled;$('voice-toggle').textContent=voicesEnabled?'Voice on':'Voice off';$('voice-toggle').setAttribute('aria-pressed',String(voicesEnabled));if(!voicesEnabled)stopVoices()};$('replay-voice').onclick=()=>{voicesEnabled=true;$('replay-voice').textContent='Replay voices';$('voice-toggle').textContent='Voice on';$('voice-toggle').setAttribute('aria-pressed','true');speakReactions()};
function renderUI(){const phase=match.phase,locked=phase!=='advice';$('mobile-next').hidden=phase!=='result'&&phase!=='complete';$('mobile-next').textContent=phase==='complete'?'Play another match':'Set next directions';$('replay-voice').hidden=!match.last||phase==='advice'||phase==='playing';$('replay-voice').disabled=false;document.querySelector('.app').classList.toggle('is-playing',phase==='playing');text('goals',match.goals);text('saves',match.saves);text('round-label',phase==='complete'?'FULL TIME':`KICK ${String(match.round).padStart(2,'0')} / 05`);text('nova-read',DIRECTIONS[match.plans.nova].toUpperCase());text('vale-read',DIRECTIONS[match.plans.vale].toUpperCase());for(const name of ['nova','vale']){const a=match.agents[name];text(`${name}-trust`,a.trust);text(`${name}-mood`,mood(a));$(`${name}-trust-bar`).style.width=`${a.trust}%`;$(`${name}-meter`).setAttribute('aria-valuenow',a.trust);$(`${name}-options`).disabled=locked;$(`${name}-promise`).checked=a.promise;$(`${name}-promise`).disabled=locked||a.advice===null;$(`${name}-silence`).disabled=locked;$(`${name}-silence`).setAttribute('aria-pressed',String(a.advice===null));document.querySelectorAll(`[data-agent="${name}"] button`).forEach(b=>b.setAttribute('aria-pressed',String(a.advice===Number(b.dataset.value))));const note=$(`${name}-note`);note.className='advice-note';note.textContent=a.advice===null?`No instruction. ${name==='nova'?'Nova':'Vale'} will decide alone.`:`You said: ${name==='nova'?'shoot':'dive'} ${DIRECTIONS[a.advice].toLowerCase()}.${a.promise?' You promised it would work.':' They may follow or make their own call.'}`;if(match.last&&(phase==='result'||phase==='complete'))text(`${name}-quote`,reviewQuote(name))}
$('kick-dots').innerHTML=Array.from({length:5},(_,i)=>{const r=match.history[i];return `<span class="kick-dot ${r?r.goal?'goal':'save':i===match.round-1?'current':''}" aria-label="Kick ${i+1}: ${r?r.goal?'goal':'save':'pending'}">${r?r.goal?'●':'×':i+1}</span>`}).join('');$('play').disabled=phase==='playing';text('play',phase==='advice'?'Let them play  ●':phase==='playing'?'Reading the moment…':phase==='complete'?'Play another match':'Next kick');text('play-note',phase==='advice'?'Same direction + both follow = a save':phase==='playing'?'Both agents have made their own choice':phase==='complete'?'A fresh match. A clean slate.':'They remember. Your next words matter.');text('phase-label',phase==='advice'?'THE QUIET BEFORE THE KICK':phase==='playing'?'NO TAKING IT BACK NOW':phase==='complete'?'FIVE KICKS. EVERY WORD COUNTED.':'THE TRUTH COMES OUT');$('field-caption').hidden=phase!=='advice';$('result-card').hidden=phase==='advice'||phase==='playing';if(phase==='result'||phase==='complete'){const r=match.last;$('result-card').classList.toggle('save',!r.goal);text('result-kicker',phase==='complete'?'FULL TIME':`KICK ${String(match.round).padStart(2,'0')}`);text('result-title',phase==='complete'?match.goals>match.saves?'NOVA WINS.':'VALE WINS.':r.goal?'GOAL.':'SAVED.');text('result-detail',phase==='complete'?`${match.goals} goals. ${match.saves} saves. Every choice counted.`:`Nova: ${DIRECTIONS[r.nova.move].toLowerCase()} (${r.reviews.nova.advice===null?"own choice":r.nova.followed?"followed you":r.nova.move===r.reviews.nova.advice?"same choice, independently":"ignored you"}). Vale: ${DIRECTIONS[r.vale.move].toLowerCase()} (${r.reviews.vale.advice===null?"own choice":r.vale.followed?"followed you":r.vale.move===r.reviews.vale.advice?"same choice, independently":"ignored you"}).`);text('debrief-label',phase==='complete'?'AFTER THE FINAL WHISTLE':'WHAT THEY REMEMBER');text('debrief-side',`Nova ${signed(r.reviews.nova.delta)} trust · Vale ${signed(r.reviews.vale.delta)} trust`)}else if(phase==='advice'){text('debrief-label',match.round===1?'IN THE TUNNEL':'BEFORE THE NEXT KICK');text('debrief-side',match.round===1?'Two rivals. One confidant.':'New instincts. Same memories.');if(match.round>1){text('nova-quote',match.agents.nova.trust<35?'“I’m watching Vale’s patterns now. Your instructions aren’t enough.”':'“A new kick. Where do you want me to shoot?”');text('vale-quote',match.agents.vale.trust<35?'“I remember the bad calls. I can choose my own dive.”':'“I’m keeping track. Where do you want me to dive?”')}}}
function signed(n){return n>0?`+${n}`:String(n)}
function select(name,direction){if(match.advise(name,direction,match.agents[name].promise)){renderUI();tone(400+100*(direction??0),.04,.02)}}
document.querySelectorAll('.direction-buttons button').forEach(b=>b.addEventListener('click',()=>select(b.parentElement.dataset.agent,Number(b.dataset.value))));for(const name of ['nova','vale']){$(`${name}-silence`).addEventListener('click',()=>select(name,null));$(`${name}-promise`).addEventListener('change',e=>{match.advise(name,match.agents[name].advice,e.target.checked);renderUI()})}
function scrollToPart(selector){if(matchMedia('(max-width:850px)').matches)document.querySelector(selector).scrollIntoView({behavior:motion.matches?'instant':'smooth',block:'start'})}
function startKick(){stopVoices();const result=match.kick();if(!result)return false;primeVoice();elapsed=0;particles=[];renderUI();tone(200,.06,.04);draw();scrollToPart('.match-column');return true}
function mainAction(){if(match.phase==='advice')startKick();else if(match.phase==='result'){stopVoices();match.next();elapsed=0;renderUI();draw();scrollToPart('.control-column')}else if(match.phase==='complete')reset()}
$('play').addEventListener('click',mainAction);$('mobile-next').addEventListener('click',mainAction);
function reset(){stopVoices();spokenRound=0;match.reset();elapsed=0;particles=[];for(const name of ['nova','vale'])text(`${name}-quote`,initialQuotes[name]);$('result-card').hidden=true;$('field-caption').querySelector('strong').innerHTML='Both sides trust you.<br>For now.';renderUI();draw();if(finishResolve){finishResolve(match.snapshot());finishResolve=null}}
$('restart').addEventListener('click',reset);$('rules-button').onclick=()=>$('rules').showModal();$('scout-help').onclick=()=>$('rules').showModal();$('close-rules').onclick=()=>$('rules').close();$('got-it').onclick=()=>$('rules').close();$('rules').addEventListener('click',e=>{if(e.target===$('rules')){const r=$('rules').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('rules').close()}});
$('sound').onclick=()=>{sound=!sound;text('sound',sound?'Sound on':'Sound off');$('sound').setAttribute('aria-pressed',String(sound));if(sound)tone(560,.08,.035)};
function tone(frequency,duration=.15,volume=.06){if(!sound)return;try{audioContext??=new(window.AudioContext||window.webkitAudioContext)();if(audioContext.state==='suspended')audioContext.resume();const osc=audioContext.createOscillator(),gain=audioContext.createGain();osc.connect(gain);gain.connect(audioContext.destination);osc.type='sine';osc.frequency.value=frequency;gain.gain.setValueAtTime(volume,audioContext.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audioContext.currentTime+duration);osc.start();osc.stop(audioContext.currentTime+duration)}catch{sound=false;text('sound','Sound unavailable')}}
function update(ms){if(match.phase==='playing'){const prev=elapsed;elapsed+=ms;const duration=motion.matches?160:1750;if(prev<450&&elapsed>=450)tone(100,.13,.09);if(elapsed>=duration){match.finish();tone(match.last.goal?760:260,.24,.08);renderUI();speakReactions();if(finishResolve){finishResolve(match.snapshot());finishResolve=null}}}frame+=ms;draw()}
const lerp=(a,b,t)=>a+(b-a)*t,clamp=(n,a=0,b=1)=>Math.max(a,Math.min(b,n));
function sprite(img,x,y,h,rotation=0){if(!img?.complete||!img.naturalWidth)return;const w=h*img.naturalWidth/img.naturalHeight;ctx.save();ctx.translate(x,y);ctx.rotate(rotation);ctx.drawImage(img,-w/2,-h,w,h);ctx.restore()}
function shadow(x,y,rx,ry,alpha=.3){ctx.fillStyle=`rgba(0,20,17,${alpha})`;ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.fill()}
function ball(x,y,r,spin=0){ctx.save();ctx.translate(x,y);ctx.rotate(spin);ctx.fillStyle='#f4f6df';ctx.strokeStyle='#153234';ctx.lineWidth=1.3;ctx.beginPath();ctx.arc(0,0,r,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.fillStyle='#153234';ctx.beginPath();for(let i=0;i<5;i++){const a=i*Math.PI*2/5-.3;const px=Math.cos(a)*r*.42,py=Math.sin(a)*r*.42;i?ctx.lineTo(px,py):ctx.moveTo(px,py)}ctx.closePath();ctx.fill();for(let i=0;i<5;i++){const a=i*Math.PI*2/5;ctx.beginPath();ctx.arc(Math.cos(a)*r*.88,Math.sin(a)*r*.88,r*.2,0,Math.PI*2);ctx.fill()}ctx.restore()}
function draw(){const W=1100,H=680;ctx.clearRect(0,0,W,H);const bg=images.stadium;if(bg?.complete&&bg.naturalWidth){ctx.drawImage(bg,0,0,W,H)}else{ctx.fillStyle='#154537';ctx.fillRect(0,0,W,H)}const shade=ctx.createLinearGradient(0,0,0,H);shade.addColorStop(0,'rgba(2,17,24,.15)');shade.addColorStop(.6,'rgba(3,30,20,0)');shade.addColorStop(1,'rgba(0,27,19,.3)');ctx.fillStyle=shade;ctx.fillRect(0,0,W,H);const active=match.phase==='playing',resolved=match.phase==='result'||match.phase==='complete';const t=active?clamp((elapsed-440)/640):resolved?1:0;const kick=active?clamp(elapsed/440):resolved?1:0;const r=match.last;const targets=[415,550,685];const dive=r&&(active||resolved)?targets[r.vale.move]:550;const shot=r&&(active||resolved)?targets[r.nova.move]:550;let kx=lerp(550,dive,1-Math.pow(1-t,3)),ky=379+(t*20),angle=r&&(active||resolved)?(r.vale.move-1)*t*.95:0;shadow(kx,369,48,8,.36);sprite(images.goalkeeper,kx,ky,147,angle);if(match.phase==='advice'){ctx.save();ctx.font='bold 11px Arial';ctx.textAlign='center';ctx.fillStyle='#ffb092';ctx.fillText('VALE  /  01',550,202);ctx.restore()}
const sx=lerp(455,490,kick),sy=lerp(540,509,kick);shadow(sx+23,sy-7,60,11,.34);sprite(images.striker,sx,sy,255-kick*12,kick*.07);let bx=550,by=481,br=12;if(active||resolved){const ease=1-Math.pow(1-t,2);bx=lerp(550,shot,ease);by=lerp(481,r?.goal?307:323,ease)-Math.sin(t*Math.PI)*44;br=lerp(12,7,t);if(t>=1&&r&&!r.goal){bx=shot+(r.nova.move===0?-15:15)*clamp((elapsed-1080)/350);by=323+25*clamp((elapsed-1080)/350)}}shadow(bx,lerp(488,357,t),br*1.4,3,.25);if(active&&t>0&&t<1&&!motion.matches){ctx.strokeStyle='rgba(236,255,164,.48)';ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(bx,by);ctx.lineTo(lerp(550,shot,clamp(t-.07)),by+25);ctx.stroke()}ball(bx,by,br,t*8);if(active&&elapsed>1090&&!motion.matches){const alpha=clamp(1-(elapsed-1090)/700);for(let i=0;i<22;i++){const angle=i*2.4,distance=(elapsed-1090)*(.045+(i%5)*.007);ctx.fillStyle=r.goal?`rgba(217,250,84,${alpha})`:`rgba(255,149,111,${alpha})`;ctx.fillRect(shot+Math.cos(angle)*distance,315+Math.sin(angle)*distance+distance*.4,3,3)}}if(match.phase==='advice'){ctx.font='bold 11px Arial';ctx.textAlign='center';ctx.fillStyle='#e5fa83';ctx.fillText('NOVA  /  09',440,558)}}
let lastFrame=performance.now();function loop(now){update(Math.min(64,now-lastFrame));lastFrame=now;requestAnimationFrame(loop)}requestAnimationFrame(loop);
window.render_game_to_text=()=>JSON.stringify({coordinateSystem:'1100×680 canvas. Origin upper-left, x right, y down. Directions are from viewer perspective.',...match.snapshot()});window.advanceTime=ms=>{update(Math.max(0,Number(ms)||0));return window.render_game_to_text()};
window.addEventListener('keydown',e=>{if($('rules').open||e.repeat)return;if(e.key.toLowerCase()==='f'&&!['INPUT','BUTTON'].includes(document.activeElement?.tagName)){if(document.fullscreenElement)document.exitFullscreen?.();else $('arena').requestFullscreen?.();}if(e.code==='Space'&&document.activeElement===document.body){e.preventDefault();mainAction()}});
function toolsRegistration(){const context=document.modelContext;if(!context?.registerTool)return;const lifecycle=new AbortController();const register=tool=>{try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}};register({name:'read_penalty_match',description:'Read the visible match, opening plans, private tips and agent trust.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>match.snapshot()});register({name:'stage_private_whispers',description:'Stage direct shot/dive instructions and promises before the next penalty; does not kick.',inputSchema:{type:'object',properties:{nova:{type:['integer','null'],enum:[0,1,2,null]},vale:{type:['integer','null'],enum:[0,1,2,null]},novaPromise:{type:'boolean'},valePromise:{type:'boolean'}},required:['nova','vale'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(match.phase!=='advice')throw new Error('Wait for the next advice phase.');if(!input||![0,1,2,null].includes(input.nova)||![0,1,2,null].includes(input.vale))throw new Error('Directions must be 0 (left), 1 (center), 2 (right), or null.');if(input.novaPromise!==undefined&&typeof input.novaPromise!=='boolean'||input.valePromise!==undefined&&typeof input.valePromise!=='boolean')throw new Error('Promises must be boolean.');match.advise('nova',input.nova,input.novaPromise);match.advise('vale',input.vale,input.valePromise);renderUI();return match.snapshot()}});register({name:'play_penalty',description:'Commit both tips, let both agents choose, and play one penalty. Returns the result after animation.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute:()=>{if(!startKick())throw new Error('A penalty can only be played in the advice phase.');return new Promise(resolve=>{finishResolve=resolve})}});window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}
renderUI();draw();toolsRegistration();
